mapper.select:
select idpuntoventa, idsucursal, puntoventa, nombrepuntoventa, numerofactura, idusuario, estadosistema, cafc, idcufd
from facturacion.puntosventas
where concat(puntoventa) ilike '%'||#{termino}||'%' and idsucursal = #{idsucursal}
order by puntoventa
limit #{cantidad} offset #{pagina}

select count(idpuntoventa)
from facturacion.puntosventas
where concat(puntoventa) ilike '%'||#{termino}||'%' and idsucursal = #{idsucursal}

select idpuntoventa, idsucursal, puntoventa, nombrepuntoventa, numerofactura, idusuario, estadosistema, cafc, idcufd
from facturacion.puntosventas
where idpuntoventa=#{id}

select idpuntoventa, idsucursal, puntoventa, nombrepuntoventa, numerofactura, idusuario, estadosistema, cafc, idcufd
from facturacion.puntosventas
where idpuntoventa=#{idpuntoventa}

select idpuntoventa
from facturacion.puntosventas
where idusuario = #{idusuario}

select numerofactura+1
from facturacion.puntosventas
where idpuntoventa = #{idpuntoventa};

select idpuntoventa
from facturacion.puntosventas
where idsucursal=#{idsucursal}
order by puntoventa
limit 1;
